import jwt from 'jsonwebtoken';

interface TokenPayload {
  sub: string;       // User ID
  roles: string[];   // Assigned roles for RBAC
  iss: string;       // Issuer authority
}

export function verifyAccessToken(token: string, publicKeyPem: string): TokenPayload {
  // Verify signature locally using asymmetric public key (RS256 / EdDSA)
  return jwt.verify(token, publicKeyPem, {
    algorithms: ['RS256'],
    issuer: 'https://auth.example.com/',
  }) as TokenPayload;
}
